selector_to_html = {"a[href=\"api.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API<a class=\"headerlink\" href=\"#api\" title=\"Link to this heading\">#</a></h1><p>Functions, broken down by category.</p>", "a[href=\"#helpful-suite2p-discussions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Helpful Suite2p Discussions<a class=\"headerlink\" href=\"#helpful-suite2p-discussions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"user_guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#additional-resources\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Additional Resources<a class=\"headerlink\" href=\"#additional-resources\" title=\"Link to this heading\">#</a></h2><h3>Helpful Suite2p Discussions<a class=\"headerlink\" href=\"#helpful-suite2p-discussions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#referenced-documentation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Referenced Documentation<a class=\"headerlink\" href=\"#referenced-documentation\" title=\"Link to this heading\">#</a></h3>", "a[href=\"metadata_reference.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Metadata Processing Reference<a class=\"headerlink\" href=\"#metadata-processing-reference\" title=\"Link to this heading\">#</a></h1><p>Complete reference for all metadata handling in LBM-Suite2p-Python.</p>", "a[href=\"#acknowledgements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Acknowledgements<a class=\"headerlink\" href=\"#acknowledgements\" title=\"Link to this heading\">#</a></h2><p>This pipeline is built on excellent open-source tools:</p>", "a[href=\"processing_flow.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Processing Flow<a class=\"headerlink\" href=\"#processing-flow\" title=\"Link to this heading\">#</a></h1><p>High-level overview of all processing steps executed by <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code>.</p>", "a[href=\"classifiers.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Suite2p ROI Classifiers<a class=\"headerlink\" href=\"#suite2p-roi-classifiers\" title=\"Link to this heading\">#</a></h1><p>Suite2p uses a logistic regression classifier to label detected ROIs as cells vs non-cells. This happens after detection and extraction, using morphological features computed from each ROI\u2019s spatial footprint.</p>", "a[href=\"glossary.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Glossary<a class=\"headerlink\" href=\"#glossary\" title=\"Link to this heading\">#</a></h1>", "a[href=\"pipeline_comparison.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Comparison<a class=\"headerlink\" href=\"#pipeline-comparison\" title=\"Link to this heading\">#</a></h1><p>This page compares how different calcium imaging analysis pipelines handle \u0394F/F calculation, neuropil correction, and spike deconvolution.</p>", "a[href=\"#lbm-suite2p-python-documentation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">LBM-Suite2p-Python Documentation<a class=\"headerlink\" href=\"#lbm-suite2p-python-documentation\" title=\"Link to this heading\">#</a></h1><p>Volumetric 2-photon calcium imaging processing pipeline using <a class=\"reference external\" href=\"https://github.com/MouseLand/suite2p\">Suite2p</a> and <a class=\"reference external\" href=\"https://cellpose.readthedocs.io/en/latest/\">Cellpose</a>.</p><p>A high-level wrapper around suite2p primarily intended for Light Beads Microscopy (LBM) datasets, but compatible with any data supported by mbo_utilities <a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/mbo_utilities/array_types.html\">imread</a></p>", "a[href=\"quickstart.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quickstart<a class=\"headerlink\" href=\"#quickstart\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/LBM-Suite2p-Python/user_guide.html\"><strong>User Guide</strong></a> |\n<a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/mbo_utilities/array_types.html#quick-reference\"><strong>Supported Filetypes</strong></a> |\n<a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/LBM-Suite2p-Python/api.html\"><strong>API Reference</strong></a> |\n<a class=\"reference external\" href=\"https://millerbrainobservatory.github.io/\"><strong>MBO Hub</strong></a></p><p>Suite2p-based calcium imaging pipeline for Light Beads Microscopy data.</p>", "a[href=\"image_gallery.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Image Gallery<a class=\"headerlink\" href=\"#image-gallery\" title=\"Link to this heading\">#</a></h1><p id=\"id1\">Visual reference for LBM-Suite2p-Python outputs and documentation.</p>", "a[href=\"projections.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Projection Images<a class=\"headerlink\" href=\"#projection-images\" title=\"Link to this heading\">#</a></h1><p>Suite2p computes several reference images during registration and detection. These images are used for quality assessment and as inputs to Cellpose anatomical segmentation.</p>", "a[href=\"postprocessing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Postprocessing Functions<a class=\"headerlink\" href=\"#postprocessing-functions\" title=\"Link to this heading\">#</a></h1><p>This guide covers the postprocessing functions available in LBM-Suite2p-Python for analyzing and refining calcium imaging traces after Suite2p extraction.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
